/**
 * BEAN Intelligence — JAZMII Auto Director: storyboard + creative-brief schema.
 *
 * The storyboard is the CREATIVE CONTRACT of an Auto Director production.
 * It is a typed, schema-validated structure — never free-form model text —
 * and every field records intent that the pipeline later executes or reports
 * on honestly:
 *
 *   - scene durations MUST sum to the requested total (duration accounting);
 *   - scene clips are generated by the EXISTING JAZMII video backend, so a
 *     scene's duration is bounded by the backend's REAL limits (3..12 s per
 *     the authorized route validation) — a longer story is expressed as more
 *     scenes, never by silently sending unsupported parameters;
 *   - aspect ratios are the three supported presets (9:16 / 16:9 / 1:1);
 *   - transitions are the vocabulary the composition engines actually
 *     implement (cut / fade) — no advertised transition that no engine can
 *     render;
 *   - audio intent is recorded as DIRECTION; the composition layer realizes
 *     only what is real (user-supplied music/voiceover today), and never
 *     claims narration exists when none was generated.
 *
 * Creative structure is BRAG-inspired (latent-spaces/brag, MIT): a distinctive
 * hook in the first seconds, a beat-by-beat scene plan, readable text holds,
 * real product moments where available, and a strong closing frame. The
 * planner adapts to the user's prompt — this schema is the shape, not a
 * single template.
 *
 * SERVER-ONLY.
 */
import { z } from 'zod'

/** Scene clip limits: the provider GENERATES only 5 s or 10 s shots (measured
 *  2026-11-20: any other duration is rejected upstream with error 1214
 *  "duration not supported"). Storyboard scenes may PLAN any whole seconds
 *  3..10 — the generation stage snaps UP to the nearest supported length and
 *  media preparation trims the clip to the planned timeline duration, so the
 *  storyboard's duration accounting stays EXACT end-to-end. */
export const SCENE_DURATION_MIN_SEC = 3
export const SCENE_DURATION_MAX_SEC = 10
/** The provider's REAL generation lengths (spec §7: never send unsupported
 *  parameters — the snap is explicit and reported). */
export const SCENE_GENERATION_LENGTHS = [5, 10] as const
export function sceneGenerationLength(plannedSec: number): number {
  for (const len of SCENE_GENERATION_LENGTHS) {
    if (plannedSec <= len) return len
  }
  return SCENE_GENERATION_LENGTHS[SCENE_GENERATION_LENGTHS.length - 1]
}

/** Production-level duration envelope (resource safety on ₹0 infrastructure). */
export const PRODUCTION_DURATION_MIN_SEC = 9
export const PRODUCTION_DURATION_MAX_SEC = 60
export const PRODUCTION_DURATION_DEFAULT_SEC = 20

/** BRAG-style default window for short promotional content. */
export const PRODUCTION_DURATION_PREFERRED_MIN = 15
export const PRODUCTION_DURATION_PREFERRED_MAX = 25

export const SCENE_COUNT_MIN = 2
export const SCENE_COUNT_MAX = 8

/** Caption bound (single readable line per scene; composition wraps). */
export const CAPTION_MAX_CHARS = 90
export const TITLE_MAX_CHARS = 80

/** Music bed gain — BRAG audio guidance: never above 0.5, 0.3–0.4 normal. */
export const MUSIC_VOLUME_DEFAULT = 0.32
export const MUSIC_VOLUME_MIN = 0.05
export const MUSIC_VOLUME_MAX = 0.5

/** Crossfade/fade duration at scene boundaries (composition-realized). */
export const FADE_DURATION_SEC = 0.4

export const CREATIVE_MODES = [
  'cinematic-film',
  'product-ad',
  'product-launch',
  'social-reel',
  'explainer',
  'story-short',
  'trailer',
  'custom',
] as const
export type CreativeMode = (typeof CREATIVE_MODES)[number]

export const CREATIVE_MODE_LABELS: Record<CreativeMode, string> = {
  'cinematic-film': 'Cinematic film',
  'product-ad': 'Product advertisement',
  'product-launch': 'Product launch / showcase',
  'social-reel': 'Social media reel',
  explainer: 'Explainer video',
  'story-short': 'Story-driven short film',
  trailer: 'Promotional trailer',
  custom: 'User-directed custom style',
}

export const ASPECT_PRESETS = ['9:16', '16:9', '1:1'] as const
export type AspectPreset = (typeof ASPECT_PRESETS)[number]

/** Canvas sizes per aspect preset (social-standard dimensions). */
export const ASPECT_CANVAS: Record<AspectPreset, { width: number; height: number }> = {
  '9:16': { width: 1080, height: 1920 },
  '16:9': { width: 1920, height: 1080 },
  '1:1': { width: 1080, height: 1080 },
}

export const ASPECT_LABELS: Record<AspectPreset, string> = {
  '9:16': 'Vertical 9:16',
  '16:9': 'Landscape 16:9',
  '1:1': 'Square 1:1',
}

/**
 * Transition vocabulary the composition engines REALLY implement:
 *  - 'cut'  — hard cut at the exact scene boundary (default);
 *  - 'fade' — dip through the background color into the next scene.
 * The planner must not emit transitions outside this set (honest mapping of
 * BRAG's richer mood vocabulary onto what the local engines can render).
 */
export const TRANSITIONS = ['cut', 'fade'] as const
export type SceneTransition = (typeof TRANSITIONS)[number]

/** Scene purpose vocabulary (BRAG beat structure, adapted). */
export const SCENE_PURPOSES = [
  'opening-hook',
  'reveal',
  'highlight',
  'product-moment',
  'punchline',
  'outro',
  'custom',
] as const
export type ScenePurpose = (typeof SCENE_PURPOSES)[number]

export const storyboardSceneSchema = z.object({
  /** Stable scene id, e.g. 'scene-01' (regeneration is keyed by index). */
  id: z
    .string()
    .min(3)
    .max(40)
    .regex(/^[a-z0-9-]+$/, 'scene id must be lowercase letters, digits or dashes'),
  /** Seconds this shot is shown. Bounded by the REAL scene-generation limits. */
  durationSeconds: z
    .number()
    .min(SCENE_DURATION_MIN_SEC)
    .max(SCENE_DURATION_MAX_SEC),
  purpose: z.enum(SCENE_PURPOSES),
  /** What the viewer sees (human-readable, shown in the UI). */
  visualDescription: z.string().min(3).max(600),
  /** The scene-specific generation prompt sent to the JAZMII video backend. */
  generationPrompt: z.string().min(3).max(600),
  /** Camera / motion direction, folded into conditioning when supported. */
  cameraDirection: z.string().max(200).optional(),
  /** Short readable caption overlaid on the scene (optional). */
  caption: z.string().max(CAPTION_MAX_CHARS).optional(),
  /** How this scene hands over to the next (last scene: 'cut' — end card follows). */
  transitionOut: z.enum(TRANSITIONS).default('cut'),
  /** Audio intent for this scene (direction only — realized where supported). */
  audioDirection: z.string().max(200).optional(),
})
export type StoryboardScene = z.infer<typeof storyboardSceneSchema>

export const storyboardSchema = z
  .object({
    title: z.string().min(1).max(TITLE_MAX_CHARS),
    /** One-sentence creative objective (what the video must achieve). */
    objective: z.string().min(3).max(300),
    /** Intended audience, free text (planner-derived, user-editable). */
    audience: z.string().max(200).optional(),
    tone: z.enum(CREATIVE_MODES),
    /** Target platform hint (display + share-copy tuning). */
    platform: z.string().max(60).optional(),
    format: z.enum(ASPECT_PRESETS),
    width: z.number().int().min(360).max(1920),
    height: z.number().int().min(360).max(1920),
    fps: z.number().int().min(12).max(60),
    /** TOTAL planned duration — scenes MUST sum to this exactly. */
    durationSeconds: z.number().int().min(PRODUCTION_DURATION_MIN_SEC).max(PRODUCTION_DURATION_MAX_SEC),
    visualDirection: z.string().min(3).max(600),
    musicDirection: z.string().max(300).optional(),
    /** Voiceover INTENT. Realized only from a user-supplied voiceover track;
     *  never auto-narrated (the pipeline cannot generate narration today and
     *  must not pretend otherwise). */
    voiceover: z.boolean().default(false),
    scenes: z.array(storyboardSceneSchema).min(SCENE_COUNT_MIN).max(SCENE_COUNT_MAX),
  })
  .superRefine((sb, ctx) => {
    // DURATION ACCOUNTING — the core storyboard invariant.
    const sum = sb.scenes.reduce((acc, s) => acc + s.durationSeconds, 0)
    if (sum !== sb.durationSeconds) {
      ctx.addIssue({
        code: 'custom',
        message: `Scene durations sum to ${sum}s but the storyboard declares ${sb.durationSeconds}s — they must match exactly.`,
        path: ['durationSeconds'],
      })
    }
    // Unique, ordered scene ids.
    const ids = new Set<string>()
    for (let i = 0; i < sb.scenes.length; i += 1) {
      const id = sb.scenes[i].id
      if (ids.has(id)) {
        ctx.addIssue({ code: 'custom', message: `Duplicate scene id "${id}".`, path: ['scenes', i, 'id'] })
      }
      ids.add(id)
    }
  })
export type Storyboard = z.infer<typeof storyboardSchema>

/** What the user submits to start a production. */
export const directorRequestSchema = z.object({
  prompt: z.string().min(3).max(2000),
  format: z.enum(ASPECT_PRESETS).default('9:16'),
  style: z.enum(CREATIVE_MODES).default('custom'),
  /** Requested total duration. Defaults to the BRAG-preferred window. */
  durationSec: z
    .number()
    .int()
    .min(PRODUCTION_DURATION_MIN_SEC)
    .max(PRODUCTION_DURATION_MAX_SEC)
    .default(PRODUCTION_DURATION_DEFAULT_SEC),
  fps: z.number().int().min(12).max(60).default(30),
  /** Optional image-to-video driver reused for scene generation (when the
   *  user wants visual grounding; identical image per scene — no invented
   *  cross-scene consistency is claimed). */
  referenceImageUrl: z
    .string()
    .max(8_000_000)
    .refine(
      (v) => /^https:\/\//.test(v) || /^data:image\/(png|jpeg|jpg|webp);base64,/.test(v),
      'referenceImageUrl must be an https URL or a base64 data URL (png/jpeg/webp).',
    )
    .optional(),
  /** Composition engine preference: 'auto' probes HyperFrames and falls back
   *  to the always-available FFmpeg engine honestly. */
  engine: z.enum(['auto', 'hyperframes', 'ffmpeg']).default('auto'),
})
export type DirectorRequest = z.infer<typeof directorRequestSchema>

/** User-supplied audio the composition layer may mix (music / voiceover). */
export const audioTrackSchema = z.object({
  /** Storage-relative path under the production's assets dir (set server-side
   *  after upload validation — never a client-controlled filesystem path). */
  path: z.string().min(1).max(400),
  role: z.enum(['music', 'voiceover']),
  volume: z.number().min(MUSIC_VOLUME_MIN).max(MUSIC_VOLUME_MAX).optional(),
  /** Declared for attribution metadata; displayed in the deliverables. */
  attribution: z.string().max(200).optional(),
})
export type AudioTrack = z.infer<typeof audioTrackSchema>

/**
 * The full persisted plan of an APPROVED production: the storyboard plus the
 * composition-affecting choices the user actually made. Stored as
 * JazmiiProduction.storyboardJson (the approved revision).
 */
export const approvedPlanSchema = z.object({
  storyboard: storyboardSchema,
  approvedAt: z.string(),
  approvedRev: z.number().int().min(1),
  enginePreference: z.enum(['auto', 'hyperframes', 'ffmpeg']).default('auto'),
  audioTracks: z.array(audioTrackSchema).max(2).default([]),
  /** Scene 3..12s bound acknowledged by the approval UI. */
  sceneLimitAck: z.boolean().default(true),
})
export type ApprovedPlan = z.infer<typeof approvedPlanSchema>

/**
 * Validate a planner-produced storyboard and return a typed result. The
 * planner retries on failure — this helper is the single gate every
 * storyboard (generated or hand-edited) must pass.
 */
export function parseStoryboard(raw: unknown): { ok: true; storyboard: Storyboard } | { ok: false; issues: string[] } {
  const parsed = storyboardSchema.safeParse(raw)
  if (parsed.success) return { ok: true, storyboard: parsed.data }
  const issues = parsed.error.issues.map(
    (i) => `${i.path.length ? i.path.join('.') : '(root)'}: ${i.message}`,
  )
  return { ok: false, issues }
}
